mapper.update:
update svc_item
category_id = #{categoryId}, code = #{code}, name = #{name}, description = #{description}, image = #{image}, price = #{price}, unit = #{unit}, duration_min = #{durationMin}, required_skill = #{requiredSkill}, status = #{status}, sort = #{sort}, update_time = #{updateTime}, update_user = #{updateUser},
where id = #{id}

mapper.select:
select i.id, i.category_id, c.name as category_name, i.code, i.name, i.description, i.price, i.unit, i.duration_min, i.required_skill, i.status, i.sort from svc_item i left join wo_category c on c.id = i.category_id
and i.name like concat('%', #{name}, '%') and i.category_id = #{categoryId} and i.status = #{status}
order by i.category_id, i.sort
